hit as (select p.id, s.link, p.affiliate_link old from sel s join products p join brands b on b.id=p.brand_id
 on lower(b.name||' - '||p.name)=lower(s.ga) or lower(b.name||' '||p.name)=lower(s.ga))
update products p set affiliate_link=hit.link from hit where p.id=hit.id
returning p.id, p.slug, hit.old;